device.kernel:
({
  create({ sr, dsp }) {
    const f = [dsp.svf(), dsp.svf(), dsp.svf(), dsp.svf()];   // two 12 dB/oct high-passes per side: 24 dB/oct
    return {
      process(L, R, n, p) {
        for (const x of f) x.set(p.cutoff, 0.707);
        for (let i = 0; i < n; i++) { L[i] = f[1].hp(f[0].hp(L[i])); R[i] = f[3].hp(f[2].hp(R[i])); }
      },
    };
  },
})
